import { SortT } from "../types";
import { getDescriptionKey } from "./getDescriptionKey";
function normalizeSearchValue(value, locale) {
    return value
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLocaleLowerCase(locale)
        .trim();
}
export function filterReceipts(receipts, query, locale) {
    const normalizedQuery = normalizeSearchValue(query || "", locale);
    if (!normalizedQuery) {
        return receipts;
    }
    return receipts.filter((receipt) => (normalizeSearchValue(receipt.shopName, locale).includes(normalizedQuery)
        || normalizeSearchValue(receipt.address, locale).includes(normalizedQuery)));
}
function getPricePerItem(price, count, pricePerKilo) {
    if (typeof pricePerKilo === "number") {
        return pricePerKilo;
    }
    return count > 1 ? price / count : price;
}
export function calculatePriceDifference(prices) {
    if (prices.length < 2 || prices[0] === 0) {
        return prices.length < 2 ? 0 : null;
    }
    const difference = ((prices[prices.length - 1] - prices[0]) / prices[0]) * 100;
    return Math.round(difference * 10) / 10;
}
export function aggregateProducts(receipts, descriptions) {
    const products = new Map();
    receipts.forEach((receipt) => {
        receipt.items.forEach((item) => {
            const key = getDescriptionKey(item.name);
            const existing = products.get(key) || {
                key,
                name: item.name,
                purchaseCount: 0,
                totalsByCurrency: {},
                prices: [],
                description: descriptions[key] || ""
            };
            existing.purchaseCount += item.count;
            existing.totalsByCurrency[receipt.currency] = (existing.totalsByCurrency[receipt.currency] || 0) + Math.round(item.price * 100);
            existing.prices.push(getPricePerItem(item.price, item.count, item.pricePerKilo));
            products.set(key, existing);
        });
    });
    return Array.from(products.values()).map((product) => {
        const currencies = Object.keys(product.totalsByCurrency);
        const currency = currencies.length === 1 ? currencies[0] : null;
        return {
            key: product.key,
            name: product.name,
            purchaseCount: product.purchaseCount,
            totalPrice: currency ? product.totalsByCurrency[currency] / 100 : 0,
            currency,
            priceDifference: calculatePriceDifference(product.prices),
            description: product.description
        };
    });
}
export function filterProducts(products, query, locale) {
    const normalizedQuery = normalizeSearchValue(query || "", locale);
    if (!normalizedQuery) {
        return products;
    }
    return products.filter((product) => (normalizeSearchValue(product.name, locale).includes(normalizedQuery)));
}
export function sortProducts(products, sort) {
    const direction = sort === SortT.PriceAsc ? 1 : -1;
    return products.slice().sort((a, b) => {
        if (!a.currency && !b.currency)
            return 0;
        if (!a.currency)
            return 1;
        if (!b.currency)
            return -1;
        return (a.totalPrice - b.totalPrice) * direction;
    });
}
export function summarizeReceipts(receipts) {
    const currencies = new Set(receipts.map((receipt) => receipt.currency));
    if (currencies.size > 1) {
        return { currency: null, total: null, average: null, isMixedCurrency: true };
    }
    const totalInMinorUnits = receipts.reduce((total, receipt) => total + Math.round(receipt.totalPrice * 100), 0);
    const total = totalInMinorUnits / 100;
    return {
        currency: receipts[0]?.currency || null,
        total,
        average: receipts.length ? total / receipts.length : 0,
        isMixedCurrency: false
    };
}
export function summarizeProducts(products) {
    const currencies = new Set(products.map((product) => product.currency).filter((currency) => Boolean(currency)));
    const hasMixedProduct = products.some((product) => !product.currency);
    if (currencies.size > 1 || hasMixedProduct) {
        return { currency: null, total: null, average: null, isMixedCurrency: true };
    }
    const totalInMinorUnits = products.reduce((total, product) => total + Math.round(product.totalPrice * 100), 0);
    return {
        currency: products[0]?.currency || null,
        total: totalInMinorUnits / 100,
        average: null,
        isMixedCurrency: false
    };
}
