import { useCallback } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { createShoppingList, loadShoppingLists, removeShoppingList, updateShoppingList } from "./utils";
export const SHOPPING_LISTS_QUERY_KEY = ["shopping-lists"];
export function useShoppingListsQuery() {
    return useQuery({
        queryKey: SHOPPING_LISTS_QUERY_KEY,
        queryFn: ({ signal }) => loadShoppingLists(signal)
    });
}
export function useShoppingListsMutations() {
    const createMutation = useMutation({ mutationFn: createShoppingList });
    const updateMutation = useMutation({
        mutationFn: ({ id, data }) => (updateShoppingList(id, data))
    });
    const deleteMutation = useMutation({ mutationFn: removeShoppingList });
    return {
        createMutation,
        updateMutation,
        deleteMutation
    };
}
export function useShoppingListsCache() {
    const queryClient = useQueryClient();
    const getList = useCallback((id) => (queryClient.getQueryData(SHOPPING_LISTS_QUERY_KEY)
        ?.find((list) => list.id === id)), [queryClient]);
    const replaceList = useCallback((shoppingList) => {
        queryClient.setQueryData(SHOPPING_LISTS_QUERY_KEY, (current = []) => (current.some((item) => item.id === shoppingList.id)
            ? current.map((item) => item.id === shoppingList.id ? shoppingList : item)
            : [shoppingList, ...current]));
    }, [queryClient]);
    const removeList = useCallback((id) => {
        queryClient.setQueryData(SHOPPING_LISTS_QUERY_KEY, (current = []) => (current.filter((list) => list.id !== id)));
    }, [queryClient]);
    return {
        getList,
        replaceList,
        removeList
    };
}
