import { deleteShoppingListRequest, getShoppingListsRequest, saveShoppingListRequest, updateShoppingListRequest } from "../../api";
import { isDeleteShoppingListResponse, isShoppingList, isShoppingListArray } from "../../utils/shoppingLists";
export async function loadShoppingLists(signal) {
    try {
        const response = await getShoppingListsRequest(signal);
        const data = await response.json();
        if (!isShoppingListArray(data)) {
            throw new Error("Invalid shopping-list response");
        }
        return data;
    }
    catch (error) {
        console.error("Failed to load shopping lists:", error);
        throw error;
    }
}
export async function createShoppingList(data) {
    try {
        const response = await saveShoppingListRequest(data);
        const shoppingList = await response.json();
        if (!isShoppingList(shoppingList)) {
            throw new Error("Invalid saved shopping-list response");
        }
        return shoppingList;
    }
    catch (error) {
        console.error("Failed to save shopping list:", error);
        throw error;
    }
}
export async function updateShoppingList(id, data) {
    try {
        const response = await updateShoppingListRequest(id, data);
        const shoppingList = await response.json();
        if (!isShoppingList(shoppingList)) {
            throw new Error("Invalid updated shopping-list response");
        }
        return shoppingList;
    }
    catch (error) {
        console.error("Failed to update shopping list:", error);
        throw error;
    }
}
export async function removeShoppingList(id) {
    try {
        const response = await deleteShoppingListRequest(id);
        const result = await response.json();
        if (!isDeleteShoppingListResponse(result)) {
            throw new Error("Invalid delete shopping-list response");
        }
    }
    catch (error) {
        console.error("Failed to delete shopping list:", error);
        throw error;
    }
}
export function toItemInput(item) {
    return {
        id: item.id,
        name: item.name,
        isCompleted: item.isCompleted
    };
}
